<?php
$fmt=static fn($v)=>\App\Service\FinanceEmployeePaymentService::formatMoney($v);$toCents=static function($v):int{$s=str_replace([' ', ','],['','.'],trim((string)$v));if(!preg_match('/^-?\d+(?:\.\d{1,2})?$/D',$s))return 0;$neg=str_starts_with($s,'-');if($neg)$s=substr($s,1);[$r,$k]=array_pad(explode('.',$s,2),2,'');$c=((int)$r*100)+(int)str_pad(substr($k,0,2),2,'0');return $neg?-$c:$c;};$fromCents=static fn(int $c):string=>($c<0?'-':'').intdiv(abs($c),100).'.'.str_pad((string)(abs($c)%100),2,'0',STR_PAD_LEFT);$months=[];$totalPaid=0;$totalReturned=0;foreach($ledger??[] as $row){$month=substr((string)$row['operation_date'],0,7);$months[$month]??=['paid'=>0,'returned'=>0,'rows'=>[]];$months[$month]['rows'][]=$row;if(($row['status']??'')==='POSTED'){$c=$toCents($row['amount']);if(($row['movement_type']??'')==='PAYMENT'){$months[$month]['paid']+=$c;$totalPaid+=$c;}else{$months[$month]['returned']+=$c;$totalReturned+=$c;}}}krsort($months);$net=$totalPaid-$totalReturned;
?>
<div class="employee-report"><div class="page-head"><div class="page-head-left"><h1 class="page-title">Выплаты сотрудникам</h1><div class="page-summary"><span>Лицевой счёт сотрудника: все выплаты из кассы и возвраты компании. Прямые выплаты с расчётного счёта не используются.</span></div></div></div><div style="display:flex;justify-content:flex-end;margin-bottom:12px"><form method="get" style="min-width:340px"><label class="field-label">Сотрудник</label><select class="field-select" name="employee_ref" onchange="this.form.submit()"><option value="">— Выберите сотрудника —</option><?php foreach($employees as $employee): ?><option value="<?= e($employee['ref']) ?>" <?= ($selectedRef??'')===$employee['ref']?'selected':'' ?>><?= e($employee['full_name']) ?></option><?php endforeach; ?></select></form></div><?php if(!$selectedEmployee): ?><div class="ux-empty"><strong>Нет данных</strong>Выберите сотрудника.</div><?php else: ?><div class="ux-summary-strip"><div>Получено от компании: <strong><?= e($fmt($fromCents($totalPaid))) ?> ₽</strong></div><div>Возвращено компании: <strong><?= e($fmt($fromCents($totalReturned))) ?> ₽</strong></div><div>Чисто получено: <strong><?= e($fmt($fromCents($net))) ?> ₽</strong></div></div><?php foreach($months as $month=>$bucket): $monthNet=$bucket['paid']-$bucket['returned']; ?><div class="table-card table-card--standard" style="margin-top:12px"><div class="table-toolbar"><div class="table-toolbar-left"><strong><?= e(date('m.Y',strtotime($month.'-01'))) ?></strong></div><div>Получено: <strong><?= e($fmt($fromCents($bucket['paid']))) ?> ₽</strong> · Возвращено: <strong><?= e($fmt($fromCents($bucket['returned']))) ?> ₽</strong> · Итого: <strong><?= e($fmt($fromCents($monthNet))) ?> ₽</strong></div></div><div class="table-scroll"><table class="table"><thead><tr><th>Дата</th><th>Операция</th><th>Источник</th><th>Основание</th><th>Получено</th><th>Возвращено</th><th>Сальдо</th></tr></thead><tbody><?php foreach($bucket['rows'] as $row):$cancelled=($row['status']??'')==='CANCELLED';$payment=($row['movement_type']??'')==='PAYMENT'; ?><tr class="<?= $cancelled?'is-muted':'' ?>"><td><?= e(date('d.m.Y',strtotime($row['operation_date']))) ?></td><td><?= $payment?'Выплата':'Возврат' ?></td><td><?= ($row['source_type']??'')==='BANK'?'Расчётный счёт (история)':'Касса' ?></td><td><?= e($row['purpose']?:($row['note']?:'—')) ?></td><td class="col-mono"><?= $payment&&!$cancelled?e($fmt($row['amount'])).' ₽':'—' ?></td><td class="col-mono"><?= !$payment&&!$cancelled?e($fmt($row['amount'])).' ₽':'—' ?></td><td class="col-mono"><strong><?= e($fmt($row['running_balance'])) ?> ₽</strong></td></tr><?php endforeach; ?></tbody></table></div></div><?php endforeach; ?><?php endif; ?></div>
